        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Record an answer
         * @description Only the user account can record an answer. The server scores it and saves her progress in the same transaction. Repeating the same clientAttemptId returns the saved attempt and does not count it again. The admin is refused even when the question exists. An exam answer names its exam as studySessionId: it is taken only while that exam is running, for a question it drew, once per question. An exam-bank question is answered only on an exam (400 exam_only without one) and never enters Review.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": components["schemas"]["Attempt"];
                };
            };
            responses: {
                /** @description This clientAttemptId was already saved. Nothing new was written. */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["SavedAttempt"];
                    };
                };
                /** @description The answer was scored and saved. */
                201: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["SavedAttempt"];
                    };
                };
                /** @description The answer does not match the question, the question is not on the exam, or an exam-bank question was sent without its exam. */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
                /** @description Sign in. */
                401: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
                /** @description The admin cannot record an answer, or a new password is required first. */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
                /** @description The question or the exam is not in the app. */
                404: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
                /** @description That clientAttemptId was already saved with a different answer, the exam has ended, or the question was already answered on this exam. */
                409: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
                /** @description Sign-in is not configured. */
                503: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["AttemptError"];
                    };
                };
            };
        };
